import { describe, expect, it } from 'vitest'
import { MockMemoryRepository } from './mockMemoryRepository'

describe('MockMemoryRepository', () => {
  it('loads the complete Memory OS demo workspace', async () => {
    const repository = new MockMemoryRepository()

    const workspace = await repository.loadWorkspace()

    expect(workspace.memoryCount).toBe(612)
    expect(workspace.changes).toHaveLength(4)
    expect(workspace.memories.map((memory) => memory.id)).toContain('flutter')
    expect(workspace.tensions[0].status).toBe('pending')
    expect(workspace.accessRules).toHaveLength(12)
  })

  it('marks a reviewed change as resolved', async () => {
    const repository = new MockMemoryRepository()

    const change = await repository.resolveChange('flutter-change', 'accept')

    expect(change.status).toBe('resolved')
    expect((await repository.loadWorkspace()).changes[0].status).toBe('resolved')
  })

  it('pins a fading memory so the state survives later reads', async () => {
    const repository = new MockMemoryRepository()

    const memory = await repository.setPinned('b2c', true)

    expect(memory.pinned).toBe(true)
    expect((await repository.loadWorkspace()).memories.find((item) => item.id === 'b2c')?.pinned).toBe(true)
  })

  it('stores the selected rule for a memory tension', async () => {
    const repository = new MockMemoryRepository()

    const tension = await repository.resolveTension('speed-quality', 'conditional')

    expect(tension.status).toBe('resolved')
    expect(tension.resolution).toBe('conditional')
  })

  it('applies a chat correction to the selected scope', async () => {
    const repository = new MockMemoryRepository()

    const correction = await repository.applyCorrection('flutter-correction', 'global')

    expect(correction.status).toBe('applied')
    expect(correction.scope).toBe('global')
  })

  it('updates one app/category access rule without changing the other rules', async () => {
    const repository = new MockMemoryRepository()

    const rule = await repository.updateAccess('app-1', '개인', true)
    const workspace = await repository.loadWorkspace()

    expect(rule.enabled).toBe(true)
    expect(workspace.accessRules.filter((item) => item.enabled)).toHaveLength(9)
  })

  it('restores every demo mutation to the original workspace', async () => {
    const repository = new MockMemoryRepository()
    await repository.setPinned('b2c', true)
    await repository.updateAccess('app-1', '개인', true)

    const workspace = await repository.resetDemo()

    expect(workspace.memories.find((item) => item.id === 'b2c')?.pinned).toBe(false)
    expect(workspace.accessRules.find((item) => item.appId === 'app-1' && item.category === '개인')?.enabled).toBe(false)
  })
})

